<span class="token comment">#atkConnect(conID, &#39;Astrogator&#39;, &#39;*/Satellite/HohmannTransfer SetValue MainSequence.SegmentList.Propagate1.StoppingConditions.Apoapsis.TripValue 0&#39;);</span>

